/* Local-only recovery of encrypted JKS generated by Universal Build Actions.
   Key and password stay in memory; nothing is sent to the dashboard or GitHub. */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.UniversalKeygen = api;
})(typeof globalThis !== "undefined" ? globalThis : this, function () {
  "use strict";
  const MAGIC = "UBKEY1";
  const ITERATIONS = 310000;
  async function decrypt(data, password, webcrypto = globalThis.crypto) {
    if (!(data instanceof ArrayBuffer) || data.byteLength < 82 || data.byteLength > 256 * 1024)
      throw new Error("Arquivo de chave criptografada inválido.");
    const bytes = new Uint8Array(data);
    const header = new TextEncoder().encode(MAGIC);
    if (!header.every((c, i) => bytes[i] === c)) throw new Error("Formato de chave não reconhecido.");
    if (typeof password !== "string" || !password.length) throw new Error("Informe sua senha de assinatura.");
    if (!webcrypto || !webcrypto.subtle) throw new Error("Abra o painel em HTTPS para desbloquear a chave.");
    const salt = bytes.slice(6, 22);
    const iv = bytes.slice(22, 34);
    const tag = bytes.slice(34, 50);
    const ciphertext = bytes.slice(50);
    const material = await webcrypto.subtle.importKey(
      "raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveKey"]);
    const key = await webcrypto.subtle.deriveKey(
      { name: "PBKDF2", salt, iterations: ITERATIONS, hash: "SHA-256" }, material,
      { name: "AES-GCM", length: 256 }, false, ["decrypt"]);
    const payload = new Uint8Array(ciphertext.length + tag.length);
    payload.set(ciphertext);
    payload.set(tag, ciphertext.length);
    try {
      return await webcrypto.subtle.decrypt(
        { name: "AES-GCM", iv, additionalData: header, tagLength: 128 },
        key, payload);
    } catch (_) {
      throw new Error("Senha incorreta ou arquivo de chave danificado.");
    }
  }
  function toBase64(arrayBuffer) {
    const bytes = new Uint8Array(arrayBuffer);
    let binary = "";
    for (let i = 0; i < bytes.length; i += 8192)
      binary += String.fromCharCode(...bytes.subarray(i, i + 8192));
    return btoa(binary);
  }
  return { decrypt, toBase64 };
});
